  latencyboss: {
    name: 'Lord Latency, Demon King of Lag', short: 'Lord Latency', sev: 150, concept: 'ratelimit', tier: 9, boss: true, sprite: 'latency', ch: 2, deep: ['at1', 'ld3', 'rl1'],
    flavor: 'He answers every request eventually. Eventually.',
    symptom: 'The kingdom\'s public API needs a rate limiter: 100 requests per user per minute across 20 API servers, a millisecond or two of overhead, and it must survive its own store failing.',
    weak: { ratelimit: 'A token bucket per user enforces the rate and allows small bursts.', atomic: 'Atomic counters in Redis stay correct across 20 servers.', gateway: 'The gateway rejects excess traffic before it costs anything.', backoff: 'Retry-After plus backoff calms his retry legions.', queue: 'A queue soaks up his bursts.' },
    resist: { vscale: 'A bigger server just lets him flood a bigger server.' },
    // Counter-question chain for the deep dive (run.js deepChain): bad, good, great, then what breaks it.
    chain: [
      { id: 'dc-latencyboss1', c: 'atomic', type: 'order', q: 'Enforce 100 requests per user per minute across 20 API servers. Rank these from weakest to strongest.', items: ['A counter in each server\'s memory, each allowing 100 a minute', 'One shared Redis counter, read with GET and then written with SET', 'A token bucket in Redis, checked and updated by one Lua script'], why: 'Local counters let a user spread over 20 servers get up to 2,000 a minute. A shared counter gives one count, but GET then SET races: two servers read 99 and both allow the request. A Lua script runs atomically in Redis, so the refill, the check and the take happen as one step, and the token bucket allows short bursts on top.' },
      { id: 'dc-latencyboss2', c: 'ratelimit', type: 'mc', q: 'Every request runs your token-bucket Lua script on a single Redis node. Traffic grows tenfold, and that node\'s CPU is pinned. What is the next move?', opts: ['Shard the buckets across a Redis Cluster by user ID', 'Run the checks on Redis read replicas to spread load', 'Move Redis to a machine with four times the CPU cores', 'Keep the buckets in Postgres rows under SELECT ... FOR UPDATE'], a: 0, no: [null, 'Every check takes a token, so it is a write, and replicas do not accept writes. They also lag. Replicas spread read-only traffic.', 'Redis runs commands and Lua scripts one at a time on its main thread, so extra cores cannot run more scripts at once.', 'Each check becomes a disk-backed transaction holding a row lock: slower, and far fewer a second than Redis. Row locks suit data that must be durable.'], why: 'Each user\'s bucket is a single key, so it lives on exactly one shard and the script stays atomic (Redis Cluster runs a script only on keys in one hash slot). Shards split the users between them, so capacity grows with each node you add.' },
      { id: 'dc-latencyboss3', c: 'ratelimit', type: 'mc', q: 'Your buckets live in a sharded Redis, one round trip per request. To skip it, a teammate wants each server to keep local buckets and sync totals with Redis every second. What does that cost?', opts: ['Limits turn approximate: users can overshoot between syncs', 'Every request waits for the next sync, adding up to a second', 'Users see extra 429s, since local buckets refill more slowly', 'Counts drift for good, since server clocks never quite agree'], a: 0, no: [null, 'The sync runs in the background, and requests are checked against the local bucket at once. Latency drops; that is the point.', 'Local buckets refill at the same rate. The error goes the other way: each server spends from its own stale view, so more gets through.', 'Each sync corrects the totals, so any error lasts at most a second. Clock skew matters for ordering events, not for counting tokens.'], why: 'Within a second, a user spread over 20 servers can spend tokens on each before the totals catch up, so the limit can briefly overshoot. That is often fine for abuse protection on a social API. For hard limits, such as login attempts or paid quotas, keep the exact shared check.' }
    ],
    pattern: [{ t: 'flood', n: 14 }, { t: 'race', n: 12 }, { t: 'retry', n: 12 }, { t: 'burst', n: 18 }, { t: 'flood', n: 20 }, { t: 'crash', n: 16 }, { t: 'escalate' }]
  },
