    resist: { hscale: 'More app servers send the same full scan faster.', replica: 'Every replica scans all 400M rows too.' },
    pattern: [{ t: 'scan', n: 12 }, { t: 'read', n: 8 }, { t: 'scan', n: 16 }, { t: 'write', n: 8 }]
